begin;
select plan(35);
select has_table('app_private','financial_eligibility_policy_versions','versioned policy exists');
select has_table('app_private','financial_eligibility_decisions','immutable decisions exist');
select has_table('app_private','financial_eligibility_overrides','override history exists');
select has_table('app_private','financial_holds','explicit holds exist');
select has_table('app_private','financial_eligibility_jobs','bounded jobs exist');
select has_function('api','financial_eligibility_simulate',array['uuid','uuid'],'simulation API exists');
select has_function('api','financial_eligibility_route_contract',array['uuid'],'route contract exists');
insert into auth.users(id,email)values('78000000-0000-4000-8000-000000000001','financial-manager@test.invalid'),('78000000-0000-4000-8000-000000000002','financial-driver@test.invalid'),('78000000-0000-4000-8000-000000000003','financial-other-region@test.invalid');
insert into public.user_profiles(user_id,display_name)values('78000000-0000-4000-8000-000000000001','Financial Manager'),('78000000-0000-4000-8000-000000000002','Financial Driver'),('78000000-0000-4000-8000-000000000003','Other Region');
insert into app_private.user_roles(user_id,role_id)select'78000000-0000-4000-8000-000000000001'::uuid,role_id from app_private.roles where role_key='director_admin' union all select'78000000-0000-4000-8000-000000000002'::uuid,role_id from app_private.roles where role_key='driver_team' union all select'78000000-0000-4000-8000-000000000003'::uuid,role_id from app_private.roles where role_key='operations_manager';
insert into app_private.user_access_scopes(user_id,scope_kind,scope_id)values('78000000-0000-4000-8000-000000000001','global',null),('78000000-0000-4000-8000-000000000003','service_region',gen_random_uuid());
insert into app_private.accounting_connections(accounting_connection_id,provider,environment_name,organization_reference,lifecycle_status)values('79000000-0000-4000-8000-000000000001','zoho-books-fake','local','synthetic','active');
insert into app_private.accounting_sync_runs(accounting_sync_run_id,accounting_connection_id,provider,environment_name,sync_mode,lifecycle_status,correlation_id,initiation_kind)values('79000000-0000-4000-8000-000000000002','79000000-0000-4000-8000-000000000001','zoho-books-fake','local','initial_full','succeeded',gen_random_uuid(),'system');
insert into app_private.client_accounting_snapshots(client_id,provider,provider_customer_id,service_region_id,currency,total_outstanding_minor,overdue_outstanding_minor,oldest_overdue_date,days_overdue,unpaid_invoice_count,overdue_invoice_count,aging_bucket,derived_status,provider_synced_at,stale_after,reconciliation_status,source_sync_run_id)values('57000000-0000-0000-0000-000000000001','zoho-books-fake','ZC-1','51000000-0000-0000-0000-000000000001','ZAR',0,0,null,0,0,0,'current','current',now(),now()+interval'48 hours','mapped','79000000-0000-4000-8000-000000000002');
select is(api.financial_eligibility_simulate('78000000-0000-4000-8000-000000000001','59000000-0000-0000-0000-000000000001')->>'suggestedStatus','eligible','current account is eligible');
select is((api.financial_eligibility_reevaluate('78000000-0000-4000-8000-000000000001','59000000-0000-0000-0000-000000000001',gen_random_uuid())->>'decision_status'),'eligible','eligible decision committed');
select is((api.financial_eligibility_route_contract('59000000-0000-0000-0000-000000000001')->>'eligibleForCollection')::boolean,true,'route contract reports eligible');
select is((select count(*)from app_private.financial_eligibility_decisions),1::bigint,'first decision recorded');
select lives_ok($$select api.financial_eligibility_reevaluate('78000000-0000-4000-8000-000000000001','59000000-0000-0000-0000-000000000001',gen_random_uuid())$$,'repeat reevaluation succeeds');
select is((select count(*)from app_private.financial_eligibility_decisions),1::bigint,'unchanged reevaluation creates no duplicate');
update app_private.client_accounting_snapshots set total_outstanding_minor=80000,overdue_outstanding_minor=80000,oldest_overdue_date=current_date-70,days_overdue=70,unpaid_invoice_count=1,overdue_invoice_count=1,aging_bucket='61_90',derived_status='seriously_overdue';
select is(api.financial_eligibility_simulate('78000000-0000-4000-8000-000000000001','59000000-0000-0000-0000-000000000001')->>'suggestedStatus','hold_recommended','serious overdue recommends hold conservatively');
select is((api.financial_eligibility_reevaluate('78000000-0000-4000-8000-000000000001','59000000-0000-0000-0000-000000000001',gen_random_uuid())->>'decision_status'),'hold_recommended','recommendation is explicit');
select is((select count(*)from app_private.financial_eligibility_decisions),2::bigint,'decision history preserved');
select is((api.financial_eligibility_hold('78000000-0000-4000-8000-000000000001','59000000-0000-0000-0000-000000000001','approved manual hold',2,gen_random_uuid())->>'decision_status'),'held','manual hold activates');
select is((api.financial_eligibility_route_contract('59000000-0000-0000-0000-000000000001')->>'reasonCode'),'financial_hold','route contract uses stable exclusion reason');
select is((select lifecycle_status from app_private.financial_holds),'active','hold lifecycle active');
select is((select count(*)from app_private.financial_eligibility_decisions),3::bigint,'hold adds history');
select is((api.financial_eligibility_override_set('78000000-0000-4000-8000-000000000001','59000000-0000-0000-0000-000000000001','eligible','approved temporary service','2099-01-01',0,gen_random_uuid())->>'decision_status'),'eligible','financial override has precedence');
select is((select derived_status from app_private.client_accounting_snapshots),'seriously_overdue','override never changes accounting facts');
select is((api.financial_eligibility_override_clear('78000000-0000-4000-8000-000000000001','59000000-0000-0000-0000-000000000001','override ended',1,gen_random_uuid())->>'decision_status'),'hold_recommended','override removal restores policy result');
select is((api.financial_eligibility_release('78000000-0000-4000-8000-000000000001','59000000-0000-0000-0000-000000000001','release original hold',5,gen_random_uuid())->>'decision_status'),'hold_recommended','original hold releases after override review');
select is((api.financial_eligibility_hold('78000000-0000-4000-8000-000000000001','59000000-0000-0000-0000-000000000001','second approved hold',6,gen_random_uuid())->>'decision_status'),'held','hold can be reapplied historically');
select is((api.financial_eligibility_release('78000000-0000-4000-8000-000000000001','59000000-0000-0000-0000-000000000001','payment review release',7,gen_random_uuid())->>'decision_status'),'hold_recommended','release produces a new decision');
select is((select lifecycle_status from app_private.financial_holds order by created_at desc limit 1),'released','hold is released, not erased');
update app_private.client_accounting_snapshots set stale_after=now()-interval'1 minute';
select is(api.financial_eligibility_simulate('78000000-0000-4000-8000-000000000001','59000000-0000-0000-0000-000000000001')->>'suggestedStatus','manual_review','stale accounting fails safe to review');
select throws_ok($$select api.financial_eligibility_detail('78000000-0000-4000-8000-000000000002','59000000-0000-0000-0000-000000000001')$$,'42501',null,'Driver denied financial eligibility');
select throws_ok($$select api.financial_eligibility_detail('78000000-0000-4000-8000-000000000003','59000000-0000-0000-0000-000000000001')$$,'42501',null,'cross-region denied');
select throws_ok('set local role authenticated;select * from app_private.financial_eligibility_decisions','42501',null,'browser table reads denied');
select ok((select count(*)>=4 from app_private.business_audit_facts where module_key='financial-eligibility'),'human commands audited');
select ok((select count(*)>=4 from app_private.outbox_events where producer_module='financial-eligibility'),'concise events emitted');
select is((select count(*)from app_private.client_services),3::bigint,'eligibility decisions never alter Client Services');
select is((select count(*)from app_private.route_operations),0::bigint,'eligibility decisions never create or alter operations');
select * from finish();rollback;
